using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using OCRS.Models; using OCRS.ViewModels.Account;
namespace OCRS.Controllers;
[Authorize] public class ProfileController(UserManager<ApplicationUser> users):Controller { public async Task<IActionResult> Index(){var u=(await users.GetUserAsync(User))!;return View(new ProfileViewModel{FullName=u.FullName,PhoneNumber=u.PhoneNumber,DateOfBirth=u.DateOfBirth,Address=u.Address});} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Index(ProfileViewModel m){if(!ModelState.IsValid)return View(m);var u=(await users.GetUserAsync(User))!;u.FullName=m.FullName;u.PhoneNumber=m.PhoneNumber;u.DateOfBirth=m.DateOfBirth;u.Address=m.Address;await users.UpdateAsync(u);TempData["Success"]="Đã cập nhật hồ sơ.";return RedirectToAction(nameof(Index));} }
